import sys,json,pathlib,hashlib,subprocess
prefix=sys.argv[1];g=pathlib.Path('docs/refactor/generated');sp=g/f'{prefix}-scope-final.json';s=json.loads(sp.read_text());ep=g/f'{prefix}-evidence.json';e=json.loads(ep.read_text());bp=g/f'{prefix}-before.json';b=json.loads(bp.read_text())
sha=lambda v:hashlib.sha256(v).hexdigest()
rows=s.get('source',s.get('sources',s.get('paths')))
for r in rows:
 if r.get('change',r.get('status'))=='deleted':continue
 assert sha(pathlib.Path(r['path']).read_bytes())==r['sha256'],r['path']
before_rows=b.get('source',b.get('sources',b.get('paths')))
if before_rows is None and 'path' in b:before_rows=[b]
expanded=g/f'{prefix}-before-expanded.json'
if expanded.exists():
 extra=json.loads(expanded.read_text());assert extra['baseCommit']==s['baseCommit']
 original={r['path']:r for r in before_rows};mapped={r['path']:r for r in extra['source']}
 for path,row in original.items():assert mapped[path]==row,path
 before_rows=extra['source']
new_before_rows=[r for r in before_rows if r.get("new") is True]
for r in new_before_rows:
 assert r.get("sha256") is None and r.get("text") in (None, ""),r["path"]
 probe=subprocess.run(["git","cat-file","-e",s["baseCommit"]+":"+r["path"]],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
 assert probe.returncode!=0,r["path"]
before_rows=[r for r in before_rows if r.get("new") is not True]
for r in before_rows:
 actual=subprocess.check_output(['git','show',s['baseCommit']+':'+r['path']]);assert sha(actual)==r['sha256'],r['path']
 if 'text' in r:assert actual.decode()==r['text'],r['path']
before_map={r['path']:r for r in before_rows}
deleted=[]
for r in s.get('deleted',[]):
 if isinstance(r,str):r={'path':r,'sha256':before_map[r]['sha256'],'expectedAbsent':True}
 else:r={**r,'sha256':r.get('sha256',r.get('beforeSHA256',r.get('beforeSha256')))}
 assert r.get('expectedAbsent') is True and not pathlib.Path(r['path']).exists(),r['path']
 assert sha(subprocess.check_output(['git','show',s['baseCommit']+':'+r['path']]))==r['sha256'],r['path']
 deleted.append(r)
for r in s.get('controls',[]):
 actual=pathlib.Path(r['path']).read_bytes();assert sha(actual)==r['sha256'],r['path'];assert subprocess.check_output(['git','show',s['baseCommit']+':'+r['path']])==actual,r['path']
art=s.get('artifacts',e.get('artifacts',[]))
for r in art: assert sha(pathlib.Path(r['path']).read_bytes())==r['sha256'],r['path']
dp=pathlib.Path('docs/refactor')/f'{prefix}.md'
document=s.get('document',s.get('documentation'))
if document:assert str(dp)==document['path'] and sha(dp.read_bytes())==document['sha256']
# 检查真实原稿与最后代码的逐项接线；不重新运行已经通过的类型、行为或证明程序。
forward=[]
if prefix=='night-and-wedding-request-construction':
 edits=json.loads((g/f'{prefix}-edits.json').read_text());bridge=json.loads((g/f'{prefix}-peer-head-bridge.json').read_text())
 for r in before_rows:
  t=r['text']
  for edit in edits[r['path']]:
   if edit.get('operation')=='prepend':t=edit['new']+t
   else:assert t.count(edit['old'])==edit.get('count',1),(r['path'],edit['old']);t=t.replace(edit['old'],edit['new'])
  if r['path']==bridge['sourceAfter']['path']:
   assert t.count(bridge['oldComment'])==1;t=t.replace(bridge['oldComment'],bridge['newComment'])
  assert t==pathlib.Path(r['path']).read_text(),r['path'];forward.append(r['path'])
report={'approved':True,'reviewer':'/root','baseCommit':s['baseCommit'],'source':rows,'deleted':deleted,'scope':{'path':str(sp),'sha256':sha(sp.read_bytes())},'document':{'path':str(dp),'sha256':sha(dp.read_bytes())},'evidence':{'path':str(ep),'sha256':sha(ep.read_bytes())},'integrity':{'freshSources':len(rows),'actualGitBefore':len(before_rows),'controls':len(s.get('controls',[])),'artifactHashes':len(art),'fullExactForward':len(forward),'mismatches':[]},'findings':[],'reviewDimensions':json.loads(sys.argv[2]),'limits':['仅实核本批冻结源码、原Git、已生成证据和真实收据；未重复任何已绿检查，不宣称完整P9完成。']}
p=g/f'{prefix}-root-review.json';p.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'review':str(p),'sha256':sha(p.read_bytes()),'integrity':report['integrity']},ensure_ascii=False))
